$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$providerScore = Decode ""

$scorePath = Join-Path $root "lib\provider-score.ts"
$groupPagePath = Join-Path $root "app\booking-groups\[id]\page.tsx"
$reviewPath = Join-Path $root "app\api\group-reviews\route.ts"

foreach ($path in @($scorePath, $groupPagePath, $reviewPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.00 : fichier requis introuvable : $path"
    }
}

$groupPage = [System.IO.File]::ReadAllText($groupPagePath)
$reviewApi = [System.IO.File]::ReadAllText($reviewPath)

if (-not $groupPage.Contains("KLYX_GROUP_MISSION_PAGE_12_87")) {
    throw "13.00 : lifecycle groupe 12.87 introuvable."
}

if (-not $reviewApi.Contains("KLYX_GROUP_REVIEW_API_12_88")) {
    throw "13.00 : review groupe 12.88 introuvable."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $scorePath -Destination ($scorePath + ".bak-13-00-" + $timestamp) -Force

[System.IO.File]::WriteAllText($scorePath, $providerScore, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.00 APPLIQUE"
Write-Host "======================================"
Write-Host "1 booking simple = 1 mission : OK"
Write-Host "1 booking group = 1 mission : OK"
Write-Host "N enfants group = 0 mission supplementaire"
Write-Host "Slots execution : CONSERVES"
Write-Host "Review groupe = 1 signal : CONSERVE"
Write-Host "Annulation groupe = 1 annulation"
Write-Host "Paiement : INCHANGE"
Write-Host "======================================"
